// A folded die-cut sticker: reflect the actual alpha mask across a moving diagonal crease.
// This keeps gaps in bicycle wheels, chair legs and foliage transparent while the paper bends.
function clippedPolygon(w,h,boundary,keepFlat) {
  const points=[{x:0,y:0},{x:w,y:0},{x:w,y:h},{x:0,y:h}];
  const score=p=>p.x/w+1-p.y/h-boundary;
  const result=[];
  for(let i=0;i<points.length;i++){
    const a=points[i],b=points[(i+1)%points.length],sa=score(a),sb=score(b);
    const insideA=keepFlat?sa<=0:sa>=0,insideB=keepFlat?sb<=0:sb>=0;
    if(insideA)result.push(a);
    if(insideA!==insideB){const t=sa/(sa-sb);result.push({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});}
  }
  return result;
}
function clip(c,points){
  c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.closePath();c.clip();
}
export function makePaperBack(sprite){
