  const c=back.getContext('2d');c.drawImage(sprite,0,0);c.globalCompositeOperation='source-in';
  const shade=c.createLinearGradient(0,0,back.width,back.height);
  shade.addColorStop(0,'#fffcf3');shade.addColorStop(.48,'#f7f5eb');shade.addColorStop(.86,'#dedfd6');shade.addColorStop(1,'#bfc6bd');
  c.fillStyle=shade;c.fillRect(0,0,back.width,back.height);return back;
}
function drawCenterSpread(c,sprite,back,w,h,progress){
  const p=Math.max(0,Math.min(1,progress)),smooth=p*p*(3-2*p);
  if(p>.995){c.drawImage(sprite,0,0,w,h);return;}
