  // The middle is anchored first; both free sides describe raised paper arcs.
  const angle=2.85*Math.pow(1-smooth,.62)+.06,radius=remaining/angle;
  c.shadowColor='transparent';c.shadowBlur=0;c.shadowOffsetY=0;
  c.drawImage(sprite,(.5-flat/w)*sprite.width,0,2*flat/w*sprite.width,sprite.height,w/2-flat,0,2*flat,h);
  const strips=28;
  for(const side of [-1,1])for(let i=0;i<strips;i++){
    const d0=remaining*i/strips,d1=remaining*(i+1)/strips;
    const point=d=>({x:w/2+side*(flat+radius*Math.sin(d/radius)),y:-radius*(1-Math.cos(d/radius))*.88});
    let a=point(d0),b=point(d1);
    let sa=(.5+side*(flat+d0)/w)*sprite.width,sb=(.5+side*(flat+d1)/w)*sprite.width;
    if(sa>sb){[sa,sb]=[sb,sa];[a,b]=[b,a];}
    const source=(d0+d1)/2/radius>Math.PI/2?back:sprite,sw=sb-sa;
    if(sw<=0)continue;
